async function main({ params }: Args): Promise<Output> {
    // 从 params 中获取当前项、索引和完整列表
    const currentItem = params.fm_item;
    const currentIndex = params.idx;
    const fullList = params.var_fm_list;
    const totalItems = fullList.length;
    const focusBookFM = params.var_focusBookFM -1;
    const preFocusBookFM = focusBookFM - 1;

    // 获取时间轴信息并设置默认值
    const preTimeline = params.pre_timeline || { start: 0, end: 100 };
    const secondMp3Timeline = params.second_mp3_timeline || { start: 70, end: 100 };

    // 安全地计算 second_mp3_timeline.start 在 pre_timeline 中的相对位置（百分比）
    let secondMp3RelativeStart = 70; // 默认值为70%

    // 确保 preTimeline 和 secondMp3Timeline 都有效
    if (preTimeline && secondMp3Timeline && 
        typeof preTimeline.start === 'number' && 
        typeof preTimeline.end === 'number' &&
        typeof secondMp3Timeline.start === 'number') {

      const totalDuration = preTimeline.end - preTimeline.start;

      // 避免除以零错误
      if (totalDuration > 0) {
        secondMp3RelativeStart = Math.min(
          Math.max(
            ((secondMp3Timeline.start - preTimeline.start) / totalDuration) * 100,
            0
          ),
          100
        );
      }
    }

    // --- 计算初始 transform_x ---
    const lastItemTransformX = 1400; // 最后一个 fm 的 transform_x 值
    const spacing = 900; // 每个 fm 之间的间距

    // 计算当前项距离最后一项有多少个"身位"
    const distanceFromLast = (totalItems - 1) - currentIndex;

    // 计算当前项的初始 transform_x
    const calculated_transform_x = lastItemTransformX - (distanceFromLast * spacing);

    // --- 优化的关键帧动画设置 ---
    // 增加更多节点以实现更丝滑的动画
    const offsets = "0|5|15|20|35|45|50|55|60|65|70|85|100";

    // 计算各阶段的 transform_x 值
    let values = "";

    // 初始位置(0%)
    let initialValue = calculated_transform_x;

    // 计算第一本书居中时的各元素位置
    const firstBookInitial = lastItemTransformX - ((totalItems - 1) * spacing);
    const offsetToFirstBook = firstBookInitial;

    // 计算第三本书居中时的各元素位置
    const thirdBookInitial = lastItemTransformX - ((totalItems - 1 - 2) * spacing);
    const offsetToThirdBook = thirdBookInitial;

    // 计算第四本书居中时的各元素位置
    const fourthBookInitial = lastItemTransformX - ((totalItems - 1 - 3) * spacing);
    const offsetToFourthBook = fourthBookInitial;

    // 第一阶段：向第一本书居中过渡
    // 缓慢开始(5%)
    const easeInValue = calculated_transform_x - (offsetToFirstBook * 0.1);

    // 加速阶段(15%)
    const accelerateValue = calculated_transform_x - (offsetToFirstBook * 0.7);

    // 第一本书居中(20%)
    let book1CenteredValue;
    if (currentIndex === 0) {
      book1CenteredValue = 0;
    } else {
      book1CenteredValue = calculated_transform_x - offsetToFirstBook;
    }

    // 开始向第三本书过渡(35%) - 加速
    const transitionToBook3Start = book1CenteredValue + 
      ((currentIndex === preFocusBookFM ? 0 : calculated_transform_x - offsetToThirdBook) - book1CenteredValue) * 0.4;

    // 接近第三本书(45%) - 减速
    const transitionToBook3End = book1CenteredValue + 
      ((currentIndex === preFocusBookFM ? 0 : calculated_transform_x - offsetToThirdBook) - book1CenteredValue) * 0.9;

    // 第三本书居中(50%)
    let book3CenteredValue;
    if (currentIndex === preFocusBookFM) {
      book3CenteredValue = 0;
    } else {
      book3CenteredValue = calculated_transform_x - offsetToThirdBook;
    }

    // 保持第三本书居中(55%) - 与50%相同
    const holdBook3 = book3CenteredValue;

    // 开始向第四本书过渡(60%) - 快速加速
    const transitionToBook4Start = book3CenteredValue + 
      ((currentIndex === focusBookFM ? 0 : calculated_transform_x - offsetToFourthBook) - book3CenteredValue) * 0.2;

    // 快速移动中(65%)
    const transitionToBook4Mid = book3CenteredValue + 
      ((currentIndex === focusBookFM ? 0 : calculated_transform_x - offsetToFourthBook) - book3CenteredValue) * 0.8;

    // 第四本书居中(70%)
    let book4CenteredValue;
    if (currentIndex === focusBookFM) {
      book4CenteredValue = 0;
    } else {
      book4CenteredValue = calculated_transform_x - offsetToFourthBook;
    }

    // 微调位置(85%) - 可能有轻微的弹性效果
    const finetuneValue = book4CenteredValue + (currentIndex === 3 ? 0 : Math.random() * 5 - 2.5);

    // 最终稳定位置(100%)
    const finalValue = book4CenteredValue;

    // 拼接关键帧值
    values = `${initialValue}|${easeInValue}|${accelerateValue}|${book1CenteredValue}|${transitionToBook3Start}|${transitionToBook3End}|${book3CenteredValue}|${holdBook3}|${transitionToBook4Start}|${transitionToBook4Mid}|${book4CenteredValue}|${finetuneValue}|${finalValue}`;

    // --- 确定要聚焦的封面索引 ---
    const focusBookIndex = focusBookFM; // 第四本书

    // 构建关键帧动画
    let keyframe1 = {};

    // 计算过渡结束时间点（确保不会是NaN）
    const transitionEndPoint = secondMp3RelativeStart + 5;

    // 确保关键帧值在合法范围内
    // 对于透明度，值必须在0-1范围内

    // 焦点封面应用放大效果，非焦点封面应用透明度效果
    if (currentIndex === focusBookIndex) {
      // 焦点封面：添加放大效果
      keyframe1 = {
        ctype: "UNIFORM_SCALE", // 均匀缩放
        offsets: `0|${secondMp3RelativeStart}|${transitionEndPoint}|100`,
        values: "0.5|0.5|0.8|0.85" // 从正常大小放大到1.2倍
      };
    } else {
      // 非焦点封面：添加透明度变化
      keyframe1 = {
        ctype: "KFTypeAlpha", // 透明度
        offsets: `0|${secondMp3RelativeStart}|${transitionEndPoint}|100`,
        values: "1|1|0|0" // 从完全不透明变为0.3透明度
      };
    }

    // 构建输出对象
    const ret = {
      "imgs": [currentItem],
      "otherInfos": {
        transform_x: calculated_transform_x,
        // 位置移动关键帧
        keyframe: {
          ctype: "KFTypePositionX",
          offsets: offsets,
          values: values,
        },
        // 根据是否为焦点封面，添加放大或透明度效果
        keyframe1: keyframe1
      }
    };

    return ret;
  }

