async function main({ params }: Args): Promise<Output> {
    const { fm_list, focusBookFM } = params;
    const focusIndex = focusBookFM - 1;
    const focusFM = fm_list[focusIndex];
    const keyframe1 = focusFM?.keyframe1;

    if (!keyframe1 || keyframe1.ctype !== 'UNIFORM_SCALE') {
      return {
        ctype: "UNIFORM_SCALE",
        offsets: "0|50",
        values: "2|0.55"
      };
    }

    const originalOffsets = keyframe1.offsets.split('|').map(v => parseFloat(v));
    const originalValues = keyframe1.values.split('|').map(v => parseFloat(v));

    const appendedOffsets: number[] = [];
    const appendedValues: number[] = [];

    let lastRefValue: number | null = null;
    let lastBorderValue: number = 0.55;

    for (let i = 0; i < originalOffsets.length; i++) {
      const offset = originalOffsets[i];
      const value = originalValues[i];

      if (offset <= 50) continue;

      appendedOffsets.push(offset);

      if (lastRefValue === null) {
        // 第一帧 offset > 50 的情况：不加，直接设置为 0.55
        appendedValues.push(0.55);
        lastBorderValue = 0.55;
      } else if (Math.abs(value - lastRefValue) < 0.0001) {
        // 稳定段，复用上一次边框值
        appendedValues.push(lastBorderValue);
      } else {
        // 发生变化，加10%
        const boosted = parseFloat((value + 0.10).toFixed(2));
        appendedValues.push(boosted);
        lastBorderValue = boosted;
      }

      lastRefValue = value;
    }

    const finalOffsets = [0, 50, ...appendedOffsets];
    const finalValues = [2, 0.55, ...appendedValues];

    return {
      ctype: "UNIFORM_SCALE",
      offsets: finalOffsets.map(v => v.toFixed(0)).join('|'),
      values: finalValues.map(v => v.toFixed(2)).join('|')
    };
  }

